"""Human-readable snapshot and conservative resource accounting."""
from common_runtime import *
import statistics
def main():
    summary=read(O/'SUMMARY.json');checks=read(O/'CHECKS.json');assert checks['passed'];rows=list(csv.DictReader((O/'accuracy_runtime.csv').open()))
